oxy_webhelp_navlinks = {"backups_archived_logs-d39307e38677":{"topics":[{"title":"Oracle backup immutability","shortdesc":"<p class=\"shortdesc\">When you archive Oracle backup data to an archival location with an immutability         policy, <span class=\"ph\">RSC<\/span> automatically protects Oracle database snapshot and log backup         files with object-level locks that prevent deletion for the duration of the retention         period.<\/p>","href":"oracle\/oracle_backup_immutability.html","attributes":{"data-id":"oracle_backup_immutability"},"menu":{"hasChildren":false},"tocID":"oracle_backup_immutability-d39307e38690","topics":[]},{"title":"Policies for archived log deletion","shortdesc":"<p class=\"shortdesc\">The Rubrik cluster can delete archived redo logs immediately, after a specified         period, or retain them indefinitely, depending on the configured policy.<\/p>","href":"oracle\/policies_for_archived_log_deletion.html","attributes":{"data-id":"policies_for_archived_log_deletion"},"menu":{"hasChildren":false},"tocID":"policies_for_archived_log_deletion-d39307e38704","topics":[]},{"title":"Archived log deletion policy delays","shortdesc":"<p class=\"shortdesc\">You can configure how long archived redo logs are retained on the Oracle host after         the Rubrik cluster completes its backup by setting a specific retention period or skipping         deletion entirely.<\/p>","href":"oracle\/config_arch_log_delet_policy_delay.html","attributes":{"data-id":"config_arch_log_delet_policy_delay"},"menu":{"hasChildren":false},"tocID":"config_arch_log_delet_policy_delay-d39307e38715","topics":[]},{"title":"Retry attempts to delete archived logs","shortdesc":"<p class=\"shortdesc\">The Rubrik cluster automatically retries an archived log deletion that         fails.<\/p>","href":"oracle\/archived_log_deletion_retry.html","attributes":{"data-id":"archived_log_deletion_retry"},"menu":{"hasChildren":false},"tocID":"archived_log_deletion_retry-d39307e38726","topics":[]}]}};